export const BODY: string = "\n<p>إضافة نص إلى صورة تستغرق دقائق معدودة فقط. ارفع الصورة واكتب كلماتك واختر خطًا ولونًا، وضع النص حيث ينتمي.</p>\n<p>في هذا البرنامج التعليمي نمر بالعملية كاملة خطوة بخطوة. سنرى طبقات مفردة ومتعددة واختيارات الخط والحجم والحدود والظلال وإعدادات التصدير التي تحافظ على النص حادًا.</p>\n<p>في النهاية ستستطيع إضافة تعليق إلى صورة أو صنع ميمز أو وسم لقطة شاشة أو تصميم رسم اجتماعي على أي جهاز. واحتفظ بالصورة الأصلية حتى تراجع النتيجة.</p>\n<h2 id=\"before-you-start\">قبل أن تبدأ: خطط لكلماتك</h2>\n<p>اكتب نصك قبل فتح الأداة. تعليق مقرر مسبقًا أقصر وأوضح من تعليق مخترع وأنت تنظر إلى المحرر.</p>\n<p>أبقه قصيرًا. عنوان من كلمات قليلة وتعليق من سطر واحد يعملان أفضل بكثير من فقرة تخفي الصورة وتُرهق المشاهد. وقرر أيضًا المزاج: خط عريض يناسب ميمز أو لافتة عرض، بينما خط زخارف خفيف يناسب صورة زفاف أو رسم اقتباس.</p>\n<p>افتح <a href=\"/ar/idafa-nass-ila-as-sura/\">أداة إضافة نص إلى صورة</a> في متصفحك. كل شيء يعمل محليًا، فصورتك لا تُرفع أبدًا إلى خادم.</p>\n<h2 id=\"step-by-step\">كيف تضيف نصًا إلى صورة في ست خطوات</h2>\n<p>العملية نفسها لتعليق أو ميمز أو وسم. ارفع واكتب ونسّق وضع وراجع ونزّل.</p>\n<p>خذ وقتك مع خطوة التنسيق. الخط والحجم واللون والحد يقررون هل النص مقروء أم يختفي في الصورة. وافتح الملف المنزّل مرة قبل مشاركته، وتأكد من أن النص يُقرأ بوضوح ولا شيء مهم من الصورة مغطى.</p>\n<ol>\n<li>ارفع صورتك بسحبها إلى منطقة الرفع أو اختيارها من جهازك أو لصق لقطة شاشة بـCtrl+V.</li>\n<li>انقر إضافة نص واكتب تعليقك في مربع محتوى النص، مستخدمًا Enter لأسطر إضافية.</li>\n<li>اختر خطًا واضبط حجم النص بين 2 بالمئة و22 بالمئة، واختر لونًا يتباين مع الصورة.</li>\n<li>أضف حدًا للنص أو ظلًا إذا كانت الخلفية مزدحمة، ثم اسحب الطبقة إلى موضعها.</li>\n<li>أضف طبقات أكثر لأسطر إضافية، مختارًا كلًا منها منفصلة لتنسيقها وحدها.</li>\n<li>اختر صيغة التصدير والجودة، ثم انقر تنزيل لحفظ الصورة ذات التعليق.</li>\n</ol>\n<h2 id=\"adding-your-first-layer\">كيف تضيف طبقة النص الأولى</h2>\n<p>انقر إضافة نص لإنشاء طبقتك الأولى. تضع الأداة تعليقًا افتراضيًا على الصورة، وتستبدله بكلماتك في مربع محتوى النص.</p>\n<p>اكتب الكلمات كما تريدها أن تظهر بالضبط. أخطاء الإملاء في صورة صعبة التجاهل، فاقرأ النص مرتين قبل المتابعة. وتظهر الطبقة في وسط الصورة افتراضيًا. اسحبها إلى الموضع الذي تريده، مثل الأعلى لعنوان أو الأسفل لتعليق.</p>\n<h2 id=\"choosing-a-font\">كيف تختار خطًا</h2>\n<p>تضم الأداة مجموعة خطوط مدمجة، من خطوط بلا زخارف عريضة إلى خطوط زخارف كلاسيكية. اختر ما يطابق مزاج صورتك ورسالتك.</p>\n<p>للميمز ولافتات العروض، استخدم خطًا بلا زخارف عريضًا. الحروف الثقيلة تبقى مقروءة في الأحجام الصغيرة والخلفيات المزدحمة، وهذا بالضبط ما يحتاجه الميمز. وللاقتباسات وصور الزفاف، استخدم خط زخارف أو خطًا أنيقًا، فالضربات الأخف تبدو رسمية وهادئة.</p>\n<h2 id=\"setting-text-size\">كيف تضبط حجم النص</h2>\n<p>يتراوح حجم النص من 2 بالمئة إلى 22 بالمئة من الصورة. العنوان يحتاج حجمًا أكبر قرب الطرف الأعلى من النطاق، بينما التعليق أو سطر الإسناد يحتاج حجمًا أصغر يبقى مقروءًا دون أن يهيمن.</p>\n<p>التحجيم بالنسبة المئوية يبقي النص متسقًا عبر أحجام صور مختلفة. نفس الضبط يبدو جيدًا في صورة مصغرة صغيرة وفي صورة كاميرا ضخمة. واختبر الحجم بالأبعاد التي ستشارك بها: عنوان يبدو عريضًا بالحجم الكامل قد يكون صغيرًا في معاينة وسائل التواصل.</p>\n<h2 id=\"choosing-a-colour\">كيف تختار لون النص</h2>\n<p>النص الأبيض يعمل على الخلفيات الداكنة والنص الأسود على الخلفيات الفاتحة، لكن معظم الصور تحتوي على الاثنين. راجع اللون مقابل المنطقة الحقيقية التي سيقف فيها النص.</p>\n<p>ضع النص فوق أنعم جزء في الصورة. تعليق فوق سماء صافية أو جدار فارغ أسهل قراءة بكثير من تعليق فوق حشد مزدحم. والألوان الساطعة قد تعمل للعناوين القصيرة، لكنها أصعب قراءة في التعليقات الطويلة. وإذا لم يعمل أي لون، أضف لوحة خلفية.</p>\n<h2 id=\"outline-and-shadow\">كيف تضيف حدًا أو ظلًا</h2>\n<p>الحد يرسم حافة حول كل حرف. حد داكن رفيع حول النص الأبيض يبقيه مقروءًا في سماء ساطعة، ولهذا يستخدمه الميمز.</p>\n<p>الظل يرفع النص عن الخلفية. يضيف حافة داكنة ناعمة خلف الحروف، ما يساعدها على البروز دون المظهر القاسي للحد. واستخدم أحدهما لا كليهما بقوة كاملة: حد مع ظل قوي يجعل النص يبدو مزدحمًا، بينما تأثير واحد يبقيه نظيفًا. ولنص ميمز كلاسيكي، استخدم حروفًا بيضاء بحد داكن سميك.</p>\n<h2 id=\"moving-layers\">كيف تحرك الطبقات وتختارها</h2>\n<p>اسحب طبقة لنقلها إلى أي مكان في الصورة. تتيح الأداة اختيار كل طبقة على حدة عندما يكون لديك عدة طبقات، فتستطيع تحرير واحدة دون لمس الأخريات.</p>\n<p>انقر الطبقة التي تريد تحريرها قبل تغيير خطها أو حجمها أو لونها. تحرير الطبقة الخاطئة خطأ شائع، ومن السهل تجنبه بمراجعة أي طبقة نشطة. والأعلى والأسفل هما الموضعان الكلاسيكيان للتعليقات: عنوان في الأعلى وخاتمة في الأسفل هو صيغة الميمز.</p>\n<h2 id=\"rotating-text\">كيف تدوّر طبقات النص</h2>\n<p>يمكن إمالة طبقات النص بزوايا مخصصة، ما يضيف طاقة إلى التصميم. عنوان مائل قليلًا يبدو ديناميكيًا، بينما النص المستقيم يبدو هادئًا ورسميًا.</p>\n<p>استخدم التدوير باعتدال. ميل صغير ببضع درجات يضيف طابعًا، بينما زاوية حادة تجعل النص صعب القراءة ويبدو كخطأ. والنص المائل يعمل جيدًا في الملصقات والرسوم الاجتماعية، حيث يجب أن يجذب التصميم الانتباه. ويسيء للتعليمات والوسوم، حيث تهم الوضوح أكثر.</p>\n<h2 id=\"multi-line-captions\">تعليقات متعددة الأسطر وتصاميم الميمز</h2>\n<p>اضغط Enter داخل مربع محتوى النص لإنشاء سطر جديد في الطبقة نفسها. هذا يتيح كتابة تعليق يمتد على سطرين أو ثلاثة دون طبقات إضافية.</p>\n<p>للميمز، استخدم طبقة للتعليق العلوي وأخرى للسفلي. الطبقات المنفصلة تتيح وضع كل سطر حيث ينتمي بالضبط. وأبقِ الأسطر قصيرة: تعليق يمتد عبر عرض الصورة كاملًا صعب القراءة، بينما الأسطر القصيرة المتمركزة على الموضوع سهلة المتابعة.</p>\n<h2 id=\"making-a-meme\">كيف تصنع ميمز في دقائق</h2>\n<p>الميمز صورة مع تعليق قصير مضحك، عادة بنص أبيض وحد داكن سميك في الأعلى والأسفل. الصيغة بسيطة، وهذه البساطة هي جوهرها.</p>\n<p>ارفع الصورة وأضف طبقة علوية للمقدمة وطبقة سفلية للخاتمة. وأبقِ كل سطر في كلمات قليلة، ليصل المزاح بسرعة. واستخدم خطًا عريضًا سميكًا بحد داكن: المظهر الكلاسيكي للميمز يبقى مقروءًا في كل خلفية تقريبًا، ولهذا أصبح المعيار.</p>\n<h2 id=\"preview-and-export\">كيف تراجع المعاينة وتصدّر</h2>\n<p>راجع المعاينة دائمًا قبل التنزيل. تحقق من أن النص يُقرأ بوضوح ولا شيء مهم من الصورة مغطى وأن الطبقات في الأماكن الصحيحة.</p>\n<p>اختر JPG للصور ذات النص بجودة عالية. حواف النص قد تلين قليلًا مع ضغط JPG، فأبقِ الجودة عالية للتعليقات الصغيرة. واختر PNG للقطات الشاشة والرسوم ذات النص، فـPNG دون فقدان، وتبقى حواف الحروف حادة، ويحافظ على الشفافية عندما تحتاجها.</p>\n<h2 id=\"adding-text-on-mobile\">كيف تضيف نصًا على الهاتف أو الجهاز اللوحي</h2>\n<p>تعمل الأداة على شاشات اللمس، فتستطيع إضافة تعليق إلى صورة على الهاتف نفسه الذي التقطها. ارفعها من معرضك واكتب النص واسحب الطبقة إلى مكانها بإصبعك.</p>\n<p>الكتابة على لوحة مفاتيح الهاتف أبطأ، فاكتب تعليقك قبل فتح الأداة. تعليق قصير ومخطط أسهل كتابة من تعليق مخترع في اللحظة. وسحب الطبقات بالإصبع أقل دقة من الفأرة: استخدم المناطق المركزية والعلوية والسفلية كأدلة، وقرّب لمراجعة الموضع.</p>\n<h2 id=\"troubleshooting\">حل المشاكل الشائعة للنص</h2>\n<p>إذا كان النص غير مقروء، فاللون يطابق الخلفية غالبًا. غيّر اللون أو أضف حدًا أو انقل الطبقة إلى جزء أنعم من الصورة.</p>\n<p>وإذا حررت الطبقة الخاطئة، انقر الطبقة التي أردت تغييرها وحاول مجددًا. تختار الأداة الطبقات واحدة في كل مرة، فراجع أيها نشطة قبل التنسيق. وإذا بدا النص ضبابيًا بعد التصدير، فقد يكون ضبط جودة JPG منخفضًا جدًا: أعد التصدير بجودة أعلى أو بدّل إلى PNG لحواف نص أحدة.</p>\n<h2 id=\"quick-tips\">نصائح سريعة لنص أفضل على الصور</h2>\n<p>أبقِ النص قصيرًا. كلمات قليلة مختارة بعناية تقوي صورة، بينما فقرة محشورة في صورة تخفي ما كان يجب أن تصفه.</p>\n<p>استخدم خطًا واحدًا للعنوان وآخر للتعليق كحد أقصى. خلط خطوط كثيرة يبدو فوضويًا، بينما زوج متسق يبقي التصميم نظيفًا. وراجع النص بالحجم الذي سيُرى به، فتعليق يبدو جيدًا بالحجم الكامل قد يكون غير مقروء في معاينة خلاصة اجتماعية.</p>\n<h2 id=\"text-on-presentation-slides\">كيف تضيف نصًا إلى صورة شريحة عرض تقديمي</h2>\n<p>الصورة المستخدمة كخلفية شريحة تحتاج غالبًا عنوانًا فوقها. أضف العنوان كطبقة نص، مستخدمًا خطًا كبيرًا وعريضًا يبقى مقروءًا من آخر القاعة.</p>\n<p>ضع العنوان فوق أنعم جزء في الصورة. عنوان فوق سماء صافية أو جدار فارغ أسهل قراءة بكثير من عنوان فوق حشد مزدحم. واستخدم حدًا داكنًا أو ظلًا عندما تكون الخلفية مزدحمة، فالتأثير يرفع الحروف عن الصورة بما يكفي لقراءتها دون إخفاء الصورة تحتها.</p>\n<p>لقواعد المقروئية، اقرأ <a href=\"/ar/blog/nasaih-li-qiraat-an-nass-ala-as-suwar/\">النص على الصور: الخطوط والتباين والمقروئية</a>. وللدليل الكامل، راجع <a href=\"/ar/blog/dalil-idafa-nass-ila-as-suwar/\">إضافة نص إلى الصور: الدليل الكامل</a>، ولوضع علامة ملكية بدل إضافة رسالة جرّب <a href=\"/ar/idafa-alama-maiyya/\">أداة العلامة المائية</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كيف أضيف نصًا إلى صورة على هاتفي؟","answer":"افتح أداة إضافة نص إلى صورة في متصفح هاتفك وارفع الصورة من معرضك والمس إضافة نص. اكتب تعليقك واختر خطًا وحجمًا واسحب الطبقة إلى موضعها بإصبعك ثم نزّل النتيجة."},{"question":"هل يمكنني إضافة تعليقين مختلفين إلى صورة؟","answer":"نعم، أضف طبقة منفصلة لكل تعليق، مثل واحدة في الأعلى وأخرى في الأسفل. ونسّق كل طبقة وحدها، فيمكن أن يكون العنوان كبيرًا وعريضًا بينما يبقى التعليق أصغر."},{"question":"لماذا يبدو نصي ضبابيًا بعد تنزيل الصورة؟","answer":"ضبط جودة JPG منخفض جدًا غالبًا هو السبب، فهو ينعّم حواف الحروف. أعد التصدير بجودة أعلى، أو بدّل إلى PNG الذي دون فقدان ويبقي حواف النص حادة."},{"question":"كيف أصنع ميمز كلاسيكيًا بنص في الأعلى والأسفل؟","answer":"ارفع الصورة وأضف طبقة للسطر العلوي وأخرى للسطر السفلي، واستخدم خطًا بلا زخارف عريضًا بالأبيض مع حد داكن سميك. وأبقِ كل سطر في كلمات قليلة ليصل المزاح بسرعة."},{"question":"هل يمكنني نقل النص بعد كتابته؟","answer":"نعم، اختر الطبقة واسحبها إلى أي مكان في الصورة. ويمكنك نقل طبقة وتغيير حجمها وإعادة تلوينها وتدويرها في أي وقت قبل التنزيل. وبعد تصدير الصورة، يندمج النص فيها ولا يمكن نقله."},{"question":"أي حجم يجب أن يكون النص لمنشور إنستغرام؟","answer":"كبير بما يكفي ليُقرأ في معاينة خلاصة صغيرة، لا بالحجم الكامل فقط. العناوين تحتاج حجمًا قرب الطرف الأعلى من نطاق 2 إلى 22 بالمئة. واختبر النتيجة بمشاهدة الصورة بحجم الخلاصة قبل النشر."}];
